module TopModule (
    input  logic        clk,
    input  logic        reset,
    output logic [2:0]  ena,
    output logic [15:0] q
);

    // Enablers for upper three digits
    // digit 0: q[3:0] (ones)
    // digit 1: q[7:4] (tens)     -> ena[0]
    // digit 2: q[11:8] (hundreds) -> ena[1]
    // digit 3: q[15:12] (thousands)-> ena[2]

    assign ena[0] = (q[3:0] == 4'd9);
    assign ena[1] = ena[0] && (q[7:4] == 4'd9);
    assign ena[2] = ena[1] && (q[11:8] == 4'd9);

    always_ff @(posedge clk) begin
        if (reset) begin
            q <= 16'd0;
        end else begin
            // Ones digit
            if (q[3:0] == 4'd9) begin
                q[3:0] <= 4'd0;

                // Tens digit
                if (q[7:4] == 4'd9) begin
                    q[7:4] <= 4'd0;

                    // Hundreds digit
                    if (q[11:8] == 4'd9) begin
                        q[11:8] <= 4'd0;

                        // Thousands digit
                        if (q[15:12] == 4'd9) begin
                            q[15:12] <= 4'd0;
                        end else begin
                            q[15:12] <= q[15:12] + 4'd1;
                        end
                    end else begin
                        q[11:8] <= q[11:8] + 4'd1;
                    end
                end else begin
                    q[7:4] <= q[7:4] + 4'd1;
                end
            end else begin
                q[3:0] <= q[3:0] + 4'd1;
            end
        end
    end

endmodule

